import{_ as s,o as a,c as i,ae as t}from"./chunks/framework.DK2I2JUh.js";const k=JSON.parse('{"title":"Chapter 1: Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"book/ch01-getting-started.md","filePath":"book/ch01-getting-started.md"}'),n={name:"book/ch01-getting-started.md"};function l(h,e,o,p,r,d){return a(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="chapter-1-getting-started" tabindex="-1">Chapter 1: Getting Started <a class="header-anchor" href="#chapter-1-getting-started" aria-label="Permalink to &quot;Chapter 1: Getting Started&quot;">​</a></h1><h2 id="installing-safec" tabindex="-1">Installing SafeC <a class="header-anchor" href="#installing-safec" aria-label="Permalink to &quot;Installing SafeC&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://raw.githubusercontent.com/safec-org/SafeC/main/install.sh</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span></span></code></pre></div><p>This installs three binaries — <code>safec</code> (the compiler), <code>safeguard</code> (the package manager and build tool, playing the same role <code>cargo</code> plays for Rust), and <code>sc-lsp</code> (the language server, for editor integration) — and wires up your shell so all three are on <code>PATH</code>. Restart your shell (or source its rc file) once the script finishes, then check it worked:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">safec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span></span></code></pre></div><p>For install-script options (custom prefix, a specific release version, building from source instead of the prebuilt release) see <a href="/safec-docs/guide/getting-started.html">Getting Started</a> in the Guide section — this chapter only covers what you need to write and run your first program.</p><h2 id="safeguard-creating-a-project" tabindex="-1"><code>safeguard</code>: creating a project <a class="header-anchor" href="#safeguard-creating-a-project" aria-label="Permalink to &quot;\`safeguard\`: creating a project&quot;">​</a></h2><p>Real SafeC projects use <code>safeguard</code>, not bare <code>safec</code> invocations — it handles the standard library, dependencies, and the compile-then-link sequence for you. Create one:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">safeguard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> new</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span></code></pre></div><p>This scaffolds:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hello/</span></span>
<span class="line"><span>├── Package.toml</span></span>
<span class="line"><span>└── src/</span></span>
<span class="line"><span>    └── main.sc</span></span></code></pre></div><p><code>Package.toml</code> is the project manifest (name, version, dependencies — <a href="/safec-docs/advanced/safeguard.html">Package Manager</a> covers its full shape later). <code>src/main.sc</code> is your entry point, and it already compiles as-is:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">safeguard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello from SafeC!</span></span></code></pre></div><h2 id="anatomy-of-a-safec-program" tabindex="-1">Anatomy of a SafeC program <a class="header-anchor" href="#anatomy-of-a-safec-program" aria-label="Permalink to &quot;Anatomy of a SafeC program&quot;">​</a></h2><p>Open <code>src/main.sc</code>:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> char*</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> fmt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, ...);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello from SafeC!</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>If you&#39;ve written C, every line of this is already familiar — that&#39;s deliberate. SafeC is a strict superset of C&#39;s syntax; the one line worth pausing on is the <code>extern</code> declaration. <code>printf</code> is a C standard library function, not a SafeC one, so it needs an explicit signature before you can call it — SafeC doesn&#39;t implicitly know what <code>printf</code> is the way a <code>#include &lt;stdio.h&gt;</code> in plain C would let you assume. You <em>can</em> still <code>#include &lt;stdio.h&gt;</code> directly:</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#include</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &lt;stdio.h&gt;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> main</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello from SafeC!</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>and SafeC will import <code>printf</code>&#39;s declaration (and everything else in the header) automatically — the compiler invokes <code>clang</code> behind the scenes to read the header and extract the declarations it needs. Both forms compile to the same thing; this book mostly writes out explicit <code>extern</code> declarations for the handful of C functions each example needs, so every example&#39;s full set of dependencies is visible in the snippet itself rather than hidden behind a header include.</p><h2 id="the-edit-compile-run-loop" tabindex="-1">The edit-compile-run loop <a class="header-anchor" href="#the-edit-compile-run-loop" aria-label="Permalink to &quot;The edit-compile-run loop&quot;">​</a></h2><p><code>safeguard run</code> is really three steps — <code>safeguard build</code> (compile everything under <code>src/</code>, link it into <code>build/hello</code>), then execute the result. While you&#39;re iterating, <code>safeguard check</code> is faster: it runs the full front end (so every type error and region-safety violation is still caught) but skips assembling and linking, since that&#39;s normally the majority of the wall-clock time. Reach for <code>check</code> while you&#39;re fixing compile errors, <code>run</code> once you want to see it actually execute:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">safeguard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # fast: did I break anything?</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">safeguard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # slower: build and execute</span></span></code></pre></div><h2 id="a-note-on-unsafe" tabindex="-1">A note on <code>unsafe</code> <a class="header-anchor" href="#a-note-on-unsafe" aria-label="Permalink to &quot;A note on \`unsafe\`&quot;">​</a></h2><p>You&#39;ll see the <code>unsafe</code> keyword show up starting in the next couple of chapters, well before Chapter 5 properly explains what it&#39;s guarding against. A one-sentence preview: SafeC tracks, at compile time, where every reference points and whether it&#39;s still valid — dereferencing a raw pointer, or converting a reference to one, steps outside what the compiler can verify, so it has to be marked explicitly. Chapter 5 is where this actually gets explained; until then, treat <code>unsafe { ... }</code> as a marker meaning &quot;trust me&quot; and move on — you&#39;ll have the full picture soon enough.</p><p>Next: <a href="/safec-docs/book/ch02-first-program.html">A First Program</a>, where we&#39;ll write something a little more substantial than &quot;Hello, world.&quot;</p>`,26)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
